public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    permuteHelper(nums, 0, result);
    return result;
}

private void permuteHelper(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        result.add(Arrays.stream(nums).boxed().collect(Collectors.toList()));
        return;
    }

    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        permuteHelper(nums, start + 1, result);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    permute(nums, used, new ArrayList<>(), result);
    return result;
}

private void permute(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            permute(nums, used, current, result);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 0) {
        return result;
    } else if (nums.length == 1) {
        result.add(Arrays.asList(nums[0]));
        return result;
    }

    for (int i = 0; i < nums.length; i++) {
        int[] newNums = remove(nums, i);
        List<List<Integer>> permutations = permute(newNums);
        for (List<Integer> permutation : permutations) {
            permutation.add(0, nums[i]);
            result.add(permutation);
        }
    }

    return result;
}

private int[] remove(int[] nums, int index) {
    int[] newNums = new int[nums.length - 1];
    System.arraycopy(nums, 0, newNums, 0, index);
    System.arraycopy(nums, index + 1, newNums, index, nums.length - index - 1);
    return newNums;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    permuteHelper(nums, 0, result);
    return result;
}

private void permuteHelper(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        List<Integer> permutation = new ArrayList<>();
        for (int num : nums) {
            permutation.add(num);
        }
        result.add(permutation);
    } else {
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            permuteHelper(nums, start + 1, result);
            swap(nums, start, i);
        }
    }
}

private void swap(int[] nums, int i, int j) {
    int tmp = nums[i];
    nums[i] = nums[j];
    nums[j] = tmp;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    boolean[] used = new boolean[nums.length];
    Arrays.fill(used, false);
    permutation(nums, used, result, new ArrayList<>());
    return result;
}

private static void permutation(int[] nums, boolean[] used, List<List<Integer>> result, List<Integer> temp) {
    if (temp.size() == nums.length) {
        result.add(new ArrayList<>(temp));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            temp.add(nums[i]);
            permutation(nums, used, result, temp);
            used[i] = false;
            temp.remove(temp.size() - 1);
        }
    }
}

