}

public static int countOilDeposits(char[][] grid) {
    // Initialize a 2D array to keep track of which cells have been visited
    boolean[][] visited = new boolean[grid.length][grid[0].length];

    // Initialize a hash set to store the positions of the oil deposits
    Set<Integer> deposits = new HashSet<>();

    // Loop through each cell in the grid
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            // If the current cell is an oil pocket
            if (grid[i][j] == '@') {
                // If the current cell has not been visited
                if (!visited[i][j]) {
                    // Mark the current cell as visited and add it to the set of oil deposits
                    visited[i][j] = true;
                    deposits.add(i * grid[0].length + j);
                }
            }
        }
    }

    // Return the number of oil deposits
    return deposits.size();
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@') {
                if (i > 0 && grid[i - 1][j] == '@') continue;
                if (j > 0 && grid[i][j - 1] == '@') continue;
                if (i < grid.length - 1 && grid[i + 1][j] == '@') continue;
                if (j < grid[0].length - 1 && grid[i][j + 1] == '@') continue;
                count++;
            }
        }
    }
    return count;
}

