public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    visited[start[0]][start[1]] = true;
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    while (!queue.isEmpty()) {
        int[] current = queue.remove();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] adjacent : paths[current[0]][current[1]]) {
            if (!visited[adjacent[0]][adjacent[1]]) {
                visited[adjacent[0]][adjacent[1]] = true;
                queue.add(adjacent);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a set to keep track of visited n-tersections
    Set<int> visited = new HashSet<>();

    // Initialize a queue to keep track of n-tersections to be explored
    Queue<int[]> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and enqueue it
    visited.add(start[0]);
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the current n-tersection
        int[] current = queue.poll();

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Get the paths from the current n-tersection
        int[][] currentPaths = paths[current[0]];

        // Loop through the paths and add the destination n-tersection to the queue if it has not been visited
        for (int[] path : currentPaths) {
            int destination = path[0];
            if (!visited.contains(destination)) {
                visited.add(destination);
                queue.offer(destination);
            }
        }
    }

    // If the queue is empty and the ending n-tersection has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(start[0]);
    visited[start[0]] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        for (int neighbor : paths[current]) {
            if (!visited[neighbor]) {
                queue.offer(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    return visited[end[0]] ? "can be travelled" : "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a 2D array to represent the maze
    boolean[][] visited = new boolean[n][n];
    // Mark the starting position as visited
    visited[start[0]][start[1]] = true;
    // Create a queue to store the positions to be visited
    Queue<int[]> queue = new LinkedList<>();
    // Enqueue the starting position
    queue.add(start);
    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue a position
        int[] current = queue.poll();
        // If the current position is the ending position, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        // Get the adjacent positions
        int[][] adjacent = getAdjacentPositions(current, n);
        // Check if any of the adjacent positions are valid and have not been visited
        for (int[] position : adjacent) {
            int x = position[0];
            int y = position[1];
            if (x >= 0 && x < n && y >= 0 && y < n && paths[x][y] == 1 && !visited[x][y]) {
                // Mark the position as visited
                visited[x][y] = true;
                // Enqueue the position
                queue.add(new int[] {x, y});
            }
        }
    }
    // If the queue is empty and the ending position has not been visited, return "cannot be travelled"
    return "cannot be travelled";
}

private static int[][] getAdjacentPositions(int[] position, int n) {
    int x = position[0];
    int y = position[1];
    int[][] adjacent = new int[4][2];
    adjacent[0] = new int[] {x - 1, y};
    adjacent[1] = new int[] {x, y + 1};
    adjacent[2] = new int[] {x + 1, y};
    adjacent[3] = new int[] {x, y - 1};
    return adjacent;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a hash set to store the n-tersections that have been visited
    Set<Integer> visited = new HashSet<>();
    // Add the starting n-tersection to the visited set
    visited.add(start[0] * n + start[1]);

    // Initialize a queue to store the n-tersections that need to be visited
    Queue<int[]> toVisit = new ArrayDeque<>();
    // Add the starting n-tersection to the queue
    toVisit.offer(start);

    while (!toVisit.isEmpty()) {
        // Get the current n-tersection from the queue
        int[] current = toVisit.poll();
        // Check if the current n-tersection is the ending n-tersection
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }
        // Loop through the paths between adjacent n-tersections
        for (int[] path : paths) {
            // Check if the current n-tersection is a starting point for the path
            if (path[0] == current[0] && path[1] == current[1]) {
                // Get the ending n-tersection of the path
                int[] ending = new int[] {path[2], path[3]};
                // Check if the ending n-tersection has not been visited already
                if (!visited.contains(ending[0] * n + ending[1])) {
                    // Add the ending n-tersection to the visited set and the queue
                    visited.add(ending[0] * n + ending[1]);
                    toVisit.offer(ending);
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int numerator = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                numerator++;
                break;
            }
        }
    }
    int denominator = word1.length() + word2.length();
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        if (word2.contains(word1.charAt(i) + "")) {
            commonLetters++;
        }
    }
    int totalLetters = word1.length() + word2.length();
    int gcd = gcd(word1.length(), word2.length());
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters * totalLetters / (gcd * gcd) + "/" + totalLetters / gcd;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

