            }
        }
    }
    return "appx(" + word1 + ", " + word2 + ") = " + count + "/" + (word1.length() + word2.length());
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }
    int sumLength = word1.length() + word2.length();
    return "appx(" + word1 + ", " + word2 + ") = " + commonLetters + "/" + sumLength;
}

public static String convertDatesToWeekdays(String date) {
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    int dayOfWeek = LocalDate.parse(date, DateTimeFormatter.ofPattern("MM dd yyyy")).getDayOfWeek().getValue();
    return dayOfWeek + ", " + weekdays[dayOfWeek - 1] + ", " + date + " is a " + weekdays[dayOfWeek - 1];
}

public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};

    String[] dateArr = date.split(" ");
    int month = Integer.parseInt(dateArr[0]);
    int day = Integer.parseInt(dateArr[1]);
    int year = Integer.parseInt(dateArr[2]);

    int weekday = (day + 2 * month + 3 * (month + 1) / 5 + year + year / 4 - year / 100 + year / 400) % 7;

    return months[month - 1] + " " + day + ", " + year + " is a " + weekdays[weekday];
}

public static String convertDatesToWeekdays(String date) {
    String[] months = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
