    int month = Integer.parseInt(dateArray[0]);
    int day = Integer.parseInt(dateArray[1]);
    int year = Integer.parseInt(dateArray[2]);
    int weekday = ((int) (2.6 * month - 0.2) + day + year + (int) (year / 4.0) + (int) (6 * year / 100.0) + (int) (year / 400.0)) % 7;
    String weekdayName = weekdays[weekday];
    String dateString = months[month - 1] + " " + day + ", " + year;
    return weekdayName + " " + dateString;
