            else left = mid + 1;
        } else {
            if (target > nums[mid] && target <= nums[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    Arrays.sort(arr);
    int start = (int) Math.ceil(n * 0.05);
    int end = (int) Math.floor(n * 0.95);
    double sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return sum / (n - 2 * start);
}

public static double trimMean(int[] arr) {
    Arrays.sort(arr);

    // Find the smallest 5% and largest 5% of the elements and their indices
    int smallestPercentileIndex = (int) (arr.length * 0.05);
    int largestPercentileIndex = (int) (arr.length * 0.95);
    int smallestElement = arr[smallestPercentileIndex];
    int largestElement = arr[largestPercentileIndex];

    // Remove the smallest 5% and largest 5% of the elements
    arr = Arrays.stream(arr).filter(x -> x != smallestElement && x != largestElement).toArray();

    // Calculate the mean of the remaining elements
    double mean = Arrays.stream(arr).sum() / (double) arr.length;

    return mean;
}

