public double trimMean(int[] arr) {
    // Calculate the size of the trimmed array
    int size = (int) Math.ceil(arr.length * 0.90);

    // Sort the array
    Arrays.sort(arr);

    // Remove the smallest 5% and largest 5% of the elements
    int[] trimmedArr = Arrays.copyOfRange(arr, (int) Math.ceil(size * 0.05), arr.length - (int) Math.ceil(size * 0.05));

    // Calculate the mean of the remaining elements
    double mean = Arrays.stream(trimmedArr).average().getAsDouble();

    return mean;
}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    Arrays.sort(arr);
    int sum = 0;
    for (int i = 0; i < n / 2; i++) {
        sum += arr[i];
    }
    if (sum % k != 0) return false;
    for (int i = n / 2; i < n; i++) {
        sum -= arr[i];
        if (sum % k != 0) return false;
    }
    return true;
}

