}

public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    if (n % 2 == 1) return false;
    Arrays.sort(arr);
    int[] counts = new int[k];
    for (int num : arr) {
        int index = num % k;
        counts[index]++;
    }
    for (int i = 1; i < counts.length; i++) {
        if (counts[i] > counts[i - 1]) return false;
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : edges[node]) {
            if (dist[neighbor] > dist[node] + (hasApple[neighbor] ? 2 : 1)) {
                dist[neighbor] = dist[node] + (hasApple[neighbor] ? 2 : 1);
                queue.offer(neighbor);
            }
        }
    }
    return dist[n - 1];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    Arrays.fill(dist, Integer.MAX_VALUE);
    dist[0] = 0;
    Queue<Integer> q = new LinkedList<>();
    q.offer(0);
    while (!q.isEmpty()) {
        int node = q.poll();
        for (int neighbor : edges[node]) {
            if (dist[neighbor] == Integer.MAX_VALUE) {
                dist[neighbor] = dist[node] + 1;
                q.offer(neighbor);
            }
        }
    }
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += dist[i];
        }
    }
    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] dist = new int[n];
    for (int i = 0; i < n; i++) {
        dist[i] = hasApple[i] ? Integer.MAX_VALUE : 0;
    }
    dist[0] = 0;
    for (int i = 0; i < n - 1; i++) {
        for (int[] edge : edges) {
            int x = edge[0];
            int y = edge[1];
            int weight = dist[x];
            if (weight != Integer.MAX_VALUE && hasApple[y]) {
                dist[y] = Math.min(dist[y], weight + 1);
            }
        }
    }
    return dist[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] distance = new int[n];
    Arrays.fill(distance, Integer.MAX_VALUE);
    distance[0] = 0;

    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int from = edge[0], to = edge[1];
            if (distance[from] != Integer.MAX_VALUE && distance[to] > distance[from] + 1) {
                distance[to] = distance[from] + 1;
            }
        }
    }

    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += distance[i];
        }
    }

    return totalTime;
}

