public String sortString(String s) {
    StringBuilder result = new StringBuilder();

    // Step 1: pick the smallest character
    char minChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) < minChar) {
            minChar = s.charAt(i);
        }
    }
    result.append(minChar);

    // Step 2: pick the smallest character that is greater than the last appended character
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) > minChar) {
            result.append(s.charAt(i));
            minChar = s.charAt(i);
            break;
        }
    }

    // Step 3: repeat step 2 until all characters are used
    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c > minChar) {
            result.append(c);
            minChar = c;
        }
    }

    // Step 4: pick the largest character
    char maxChar = s.charAt(s.length() - 1);
    result.append(maxChar);

    // Step 5: pick the largest character that is smaller than the last appended character
    for (int i = s.length() - 2; i >= 0; i--) {
        if (s.charAt(i) < maxChar) {
            result.append(s.charAt(i));
            maxChar = s.charAt(i);
            break;
        }
    }

    // Step 6: repeat step 5 until all characters are used
    for (int i = s.length() - 2; i >= 0; i--) {
        char c = s.charAt(i);
        if (c < maxChar) {
            result.append(c);
            maxChar = c;
        }
    }

    return result.toString();
}

