public int uniqueMorseRepresentations(String[] words) {
    HashSet<String> morseCodes = new HashSet<>();
    for (String word : words) {
      StringBuilder sb = new StringBuilder();
      for (char c : word.toCharArray()) {
        sb.append(getMorseCode(c));
      }
      morseCodes.add(sb.toString());
    }
    return morseCodes.size();
  }

private String getMorseCode(char c) {
    // Implement the mapping between letters and Morse codes
    // For example, "a" maps to ".-", "b" maps to "-..." and so on
    switch (c) {
      case 'a': return ".-";
      case 'b': return "-...";
      case 'c': return "-.-.";
      case 'd': return "-..";
      case 'e': return ".";
      case 'f': return "..-.";
      case 'g': return "--.";
      case 'h': return "....";
      case 'i': return "..";
      case 'j': return ".---";
      case 'k': return "-.-";
      case 'l': return ".-..";
      case 'm': return "--";
      case 'n': return "-.";
      case 'o': return "---";
      case 'p': return ".--.";
      case 'q': return "--.-";
      case 'r': return ".-.";
      case 's': return "...";
      case 't': return "-";
      case 'u': return "..-";
      case 'v': return "...-";
      case 'w': return ".--";
      case 'x': return "-..-";
      case 'y': return "-.--";
      case 'z': return "--..";
      default: return "";
    }
  }

public int uniqueMorseRepresentations(String[] words) {
