public boolean hasAllCodes(String s, int k) {
    // Base case: if s is empty, return false
    if (s.length() == 0) {
        return false;
    }

    // Create a set to store all possible substrings of length k
    Set<String> set = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        set.add(s.substring(i, i + k));
    }

    // Check if set contains all possible substrings of length k
    for (int i = 0; i <= s.length() - k; i++) {
        if (!set.contains(s.substring(i, i + k))) {
            return false;
        }
    }

    // If all substrings of length k are present in the set, return true
    return true;
}

public boolean hasAllCodes(String s, int k) {
    // Create a set to store all possible binary strings of length k
    Set<String> binaryStrings = new HashSet<>();
    for (int i = 0; i < (1 << k); i++) {
        binaryStrings.add(getBinaryString(i, k));
    }

    // Check if all binary strings of length k are substrings of s
    for (String binaryString : binaryStrings) {
        if (!s.contains(binaryString)) {
            return false;
        }
    }

    return true;
}

private static String getBinaryString(int num, int k) {
    String binaryString = Integer.toBinaryString(num);
    while (binaryString.length() < k) {
        binaryString = "0" + binaryString;
    }
    return binaryString;
}

