public int findMinFibonacciNumbers(int k) {
    int i = 0;
    int[] fib = {1, 1};
    while (fib[i] < k) {
        int temp = fib[i];
        fib[i] = fib[i] + fib[i + 1];
        fib[i + 1] = temp;
        i++;
    }
    int count = 0;
    while (k > 0) {
        count++;
        k -= fib[i];
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int minFibonacciNumbers = 0;
    int currentFibonacciNumber = 1;
    int previousFibonacciNumber = 1;
    while (currentFibonacciNumber <= k) {
        if (currentFibonacciNumber + previousFibonacciNumber <= k) {
            currentFibonacciNumber += previousFibonacciNumber;
            previousFibonacciNumber = currentFibonacciNumber - previousFibonacciNumber;
            minFibonacciNumbers++;
        } else {
            break;
        }
    }
    return minFibonacciNumbers;
}

public int findMinFibonacciNumbers(int k) {
    int fn1 = 1, fn2 = 1;
    int count = 0;
    while (k > 0) {
        if (k >= fn2) {
            k -= fn2;
            fn1 = fn2;
            fn2 += fn1;
            count++;
        } else {
            k = k - fn1;
            fn1 = fn2 - fn1;
            fn2 = fn1 + fn2;
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int minFibonacciNumbers = 0;
    int n = 2;
    int fibonacciNumber = 1;
    while (fibonacciNumber < k) {
        if (fibonacciNumber + fibonacciNumber <= k) {
            minFibonacciNumbers++;
            k -= fibonacciNumber;
        }
        n++;
        fibonacciNumber = fibonacci(n);
    }
    return minFibonacciNumbers;
}

int fibonacci(int n) {
    if (n <= 2) {
        return 1;
    } else {
        return fibonacci(n - 1) + fibonacci(n - 2);
    }
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    // Use a HashSet to store the factors of n
    HashSet<Integer> factors = new HashSet<>();
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
        }
    }

    // Convert the HashSet to an array and sort it in ascending order
    Integer[] sortedFactors = factors.toArray(new Integer[0]);
    Arrays.sort(sortedFactors);

    // Check if there are at least k factors
    if (sortedFactors.length < k) {
        return -1;
    }

    // Return the kth factor
    return sortedFactors[k - 1];
}

public int kthFactor(int n, int k) {
    List<Integer> factors = new ArrayList<>();
    for (int i = 1; i <= (int) Math.sqrt(n); i++) {
        if (n % i == 0) {
            factors.add(i);
            if (n / i != i) {
                factors.add(n / i);
            }
        }
    }
    Collections.sort(factors);
    return factors.size() >= k ? factors.get(k - 1) : -1;
}

