public int maxUniqueSplit(String s) {
    int n = s.length();
    Set<String> substrings = new HashSet<>();
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String substring = s.substring(i, j);
            if (substring.length() > 1 && substrings.add(substring)) {
                int maxLength = Math.max(maxUniqueSplit(s.substring(0, i)), maxUniqueSplit(s.substring(j, n)));
                return Math.max(maxLength, substrings.size());
            }
        }
    }
    return 1;
}

public int maxUniqueSplit(String s) {
    // create a set to store unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();
    // create a variable to store the maximum number of unique substrings
    int max = 0;
    // loop through each possible starting index
    for (int i = 0; i < s.length(); i++) {
        // loop through each possible ending index
        for (int j = i + 1; j <= s.length(); j++) {
            // check if the substring is unique
            if (!uniqueSubstrings.contains(s.substring(i, j))) {
                // if it is unique, add it to the set
                uniqueSubstrings.add(s.substring(i, j));
                // update the maximum number of unique substrings
                max = Math.max(max, uniqueSubstrings.size());
            }
        }
    }
    return max;
}

