public String getSmallestString(int n, int k) {
    if (n == 1) {
        return "a";
    }
    String smallestString = "";
    while (k > 0) {
        int charValue = k % 26;
        char c = (char) ('a' + charValue);
        smallestString = c + smallestString;
        k = (k - charValue) / 26;
        n--;
    }
    return smallestString;
}

public String getSmallestString(int n, int k) {
    String smallest = "";
    for (int i = 0; i < n; i++) {
        smallest += (char)('a' + (k - 1) % 26);
        k = (k - 1) / 26;
    }
    return smallest;
}

public static String getSmallestString(int n, int k) {
    int remaining = k;
    char[] alphabet = new char[n];
    for (int i = n - 1; i >= 0; i--) {
        int value = remaining - i * (n - i);
        if (value > 0) {
            alphabet[i] = 'a' + value - 1;
            remaining = value - 1;
        } else {
            alphabet[i] = 'z';
        }
    }
    return new String(alphabet);
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = (char) ((k - (n - i)) % 26 + 'a');
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
