    String result = "";
    int[] lengths = new int[n];
    for (int i = 0; i < n; i++) {
        if (i == 0) {
            lengths[i] = (k - 1) % 26 + 1;
        } else {
            lengths[i] = (k - 1) / (26 ^ (i - 1)) % 26 + 1;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < alphabet.length; j++) {
            if (lengths[i] == j + 1) {
                result += alphabet[j];
                break;
            }
        }
    }
    return result;
}

