public static int longestLine(int[][] mat) {
    int maxLength = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                int currLength = 1;
                // Horizontal line
                for (int k = j + 1; k < mat[0].length && mat[i][k] == 1; k++) {
                    currLength++;
                }
                // Vertical line
                for (int k = i + 1; k < mat.length && mat[k][j] == 1; k++) {
                    currLength++;
                }
                // Diagonal line
                for (int k = 1; i + k < mat.length && j + k < mat[0].length && mat[i + k][j + k] == 1; k++) {
                    currLength++;
                }
                // Anti-diagonal line
                for (int k = 1; i - k >= 0 && j + k < mat[0].length && mat[i - k][j + k] == 1; k++) {
                    currLength++;
                }
                maxLength = Math.max(maxLength, currLength);
            }
        }
    }
    return maxLength;
}

public static int longestLine(int[][] mat) {
    int m = mat.length;
    int n = mat[0].length;
    int[][] d = new int[m][n];
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                d[i][j] = 1;
                if (i > 0 && j > 0 && d[i - 1][j] > 0 && d[i][j - 1] > 0) {
                    d[i][j] = Math.max(d[i][j], d[i - 1][j] + d[i][j - 1]);
                }
            }
        }
    }
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (d[i][j] > maxLength) {
                maxLength = d[i][j];
            }
        }
    }
    return maxLength;
}

