public static int longestLine(int[][] mat, boolean[][] visited, int row, int col) {
    if(row < 0 || col < 0 || col >= mat[0].length || row >= mat.length || visited[row][col] || mat[row][col] == 0) {
        return 0;
    }
    visited[row][col] = true;
    return 1 + longestLine(mat, visited, row - 1, col) + longestLine(mat, visited, row, col - 1) + longestLine(mat, visited, row + 1, col) + longestLine(mat, visited, row, col + 1);
}

public static int longestLine(int[][] mat) {
    int maxLength = 0;

    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            if (mat[i][j] == 1) {
                maxLength = Math.max(maxLength, findMaxLength(mat, i, j));
            }
        }
    }

    return maxLength;
}

private static int findMaxLength(int[][] mat, int i, int j) {
    int length = 1;
    int rows = mat.length;
    int cols = mat[0].length;

    for (int k = 1; i + k < rows && j + k < cols && mat[i + k][j + k] == 1; k++) {
        length++;
    }

    for (int k = 1; i + k < rows && j - k >= 0 && mat[i + k][j - k] == 1; k++) {
        length++;
    }

    for (int k = 1; i - k >= 0 && j + k < cols && mat[i - k][j + k] == 1; k++) {
        length++;
    }

    for (int k = 1; i - k >= 0 && j - k >= 0 && mat[i - k][j - k] == 1; k++) {
        length++;
    }

    return length;
}

