public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;
    Map<Integer, Integer> map = new HashMap<>();

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && A[i] + A[j] <= A[i] * A[j]) {
                int key = (A[i] * A[j] - A[i - 1] - A[j - 1]) / 2;
                map.put(key, map.getOrDefault(key, 0) + 1);
            }
        }
    }

    for (int key : map.keySet()) {
        int value = map.get(key);
        count += value * (value - 1) / 2;
    }

    return count;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int count = 0;
    int[] permutation;
    int[] temp;

    for (int i = 0; i < n; i++) {
        permutation = new int[n];
        temp = new int[n];
        Arrays.fill(permutation, -1);
        Arrays.fill(temp, -1);
        permutation[0] = A[i];
        generatePermutations(A, i + 1, permutation, temp, n, count);
    }

    return count;
}

private static void generatePermutations(int[] A, int index, int[] permutation, int[] temp, int n, int count) {
    if (index == n) {
        boolean isSquare = true;
        for (int i = 0; i < n - 1; i++) {
            if (Math.sqrt(permutation[i] + permutation[i + 1]) != (int) Math.sqrt(permutation[i] + permutation[i + 1])) {
                isSquare = false;
                break;
            }
        }
        if (isSquare) count++;
        return;
    }

    for (int i = 0; i < n; i++) {
        if (temp[i] == -1) {
            permutation[index] = A[i];
            temp[i] = 1;
            generatePermutations(A, index + 1, permutation, temp, n, count);
            temp[i] = -1;
        }
    }
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] count = new int[n];
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            int diff = A[i] - A[j];
            if (isPerfectSquare(diff)) {
                count[i] += dp[j][i];
            }
        }
    }
    for (int[] row : dp) {
        Arrays.fill(row, 1);
    }
    for (int i = 0; i < n; i++) {
        int tmp = 0;
        for (int j = 0; j < i; j++) {
            if (A[j] < A[i]) {
                tmp += dp[j][i] * count[j];
            }
        }
        dp[i][i] = tmp + 1;
    }
    return dp[n - 1][n - 1];
}

public static boolean isPerfectSquare(int n) {
    int sqrt = (int) Math.sqrt(n);
    return sqrt * sqrt == n;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] dp = new int[n + 1];
    Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            int sum = A[i] + A[j];
            if (isSquare(sum)) {
                dp[i] = Math.min(dp[i], dp[j] + (i == j ? 1 : 0));
            }
        }
    }

    return dp[n - 1];
}

