public static int findSmallestInteger(int n) {
    int[] digits = GetDigits(n);
    Array.Sort(digits);
    return GetNumberFromDigits(digits);
}

private static int[] GetDigits(int n) {
    int[] digits = new int[n.ToString().Length];
    for (int i = 0; i < digits.Length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }
    return digits;
}

private static int GetNumberFromDigits(int[] digits) {
    int result = 0;
    for (int i = 0; i < digits.Length; i++) {
        result += digits[i] * (int)Math.Pow(10, i);
    }
    return result;
}

public static int findSmallestInteger(int n) {
    String nStr = String.valueOf(n);
    String[] digits = nStr.split("");
    Arrays.sort(digits);
    while (true) {
        if (Integer.parseInt(String.join("", digits)) > n) {
            return Integer.parseInt(String.join("", digits));
        }
        int lastDigit = digits[digits.length - 1];
        digits[digits.length - 1] = digits[0];
        digits[0] = lastDigit;
        Arrays.sort(digits);
    }
}

public static int findSmallestInteger(int n) {
    int smallest = -1;
    int current = -1;
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;
    int count = 0;
    while (count < length) {
        int num = 0;
        for (int i = 0; i < length; i++) {
            num += Character.getNumericValue(digits[i]) * Math.pow(10, length - i - 1);
        }
        current = num;
        if (num > n && num < smallest) {
            smallest = num;
        }
        count++;
    }
    return smallest;
}

