public static int findSmallestInteger(int n) {
    // Generate all possible permutations of the digits of n
    String[] permutations = permutate(Integer.toString(n));

    // Sort the permutations in ascending order
    Arrays.sort(permutations);

    // Find the first permutation that is greater than n
    for (String permutation : permutations) {
        if (Integer.parseInt(permutation) > n) {
            return Integer.parseInt(permutation);
        }
    }

    // If no permutation is greater than n, return -1
    return -1;
}

public static String[] permutate(String str) {
    int n = str.length();
    if (n == 1) {
        return new String[] { str };
    } else {
        String[] permutations = new String[n * (n - 1) / 2];
        int k = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                permutations[k++] = str.substring(0, i) + str.charAt(j) + str.substring(i, j) + str.charAt(i) + str.substring(j + 1);
            }
        }
        return permutations;
    }
}

