private static boolean isCenterSymmetric(int num, int n) {
    if (num == 0) {
        return n == 1;
    }
    String str = num + "";
    if (str.length() != n) {
        return false;
    }
    int start = str.length() / 2;
    int end = str.length() - 1 - start;
    while (start >= 0 && end >= 0) {
        if (str.charAt(start) != str.charAt(end)) {
            return false;
        }
        start--;
        end--;
    }
    return true;
}

