        int middle = num.length() / 2;
        String mid = num.substring(middle - 1, middle + 1);
        int size = result.size();
        for (int j = 0; j < size; j++) {
            String r = result.get(j);
            int rMiddle = r.length() / 2;
            String rMid = r.substring(rMiddle - 1, rMiddle + 1);
            if (rMid.equals(mid)) {
                result.add(num);
            }
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the points form a simple polygon with three points
    if (points.length != 3) return false;

    // Check if the points form a line
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    if (p1[0] == p2[0] && p2[0] == p3[0]) return false;
    if (p1[1] == p2[1] && p2[1] == p3[1]) return false;

    // Check if the points form a boomerang
    int area = p1[0] * p2[1] + p2[0] * p3[1] + p3[0] * p1[1] - p1[1] * p2[0] - p2[1] * p3[0] - p3[1] * p1[0];
    return area == 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    return (x1 * y2 + x2 * y3 + x3 * y1 == x2 * y1 + x3 * y2 + x1 * y3)
        && (x1 * y2 + x2 * y3 + x3 * y1 != x1 * y3 + x2 * y1 + x3 * y2)
        && (x1 * y3 + x2 * y1 + x3 * y2 == x2 * y3 + x3 * y1 + x1 * y2)
        && (x1 * y3 + x2 * y1 + x3 * y2 != x1 * y1 + x2 * y2 + x3 * y3);
}

public static boolean isBoomerang(int[][] points) {
