    int x1 = points[0][0], y1 = points[0][1], x2 = points[1][0], y2 = points[1][1], x3 = points[2][0], y3 = points[2][1];
    return x1 * y2 + x2 * y3 + x3 * y1 != x1 * y3 + x2 * y1 + x3 * y2;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length == 3) {
        int[] p1 = points[0];
        int[] p2 = points[1];
        int[] p3 = points[2];
        double d12 = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
        double d23 = Math.hypot(p3[0] - p2[0], p3[1] - p2[1]);
        double d13 = Math.hypot(p3[0] - p1[0], p3[1] - p1[1]);
        return d12 > 0 && d23 > 0 && d13 > 0 && (d12 + d23 > d13 && d12 + d13 > d23);
    }
    return false;
}

public static boolean isBoomerang(int[][] points) {
    // Check if the array is null or has less than 3 elements
    if (points == null || points.length < 3) return false;

    // Get the first point
    int[] p1 = points[0];
    // Get the second point
    int[] p2 = points[1];
    // Get the third point
    int[] p3 = points[2];

    // Calculate the angles between the first two points and the third point
    int a1 = Math.abs(p1[0] - p3[0]) + Math.abs(p1[1] - p3[1]);
    int a2 = Math.abs(p2[0] - p3[0]) + Math.abs(p2[1] - p3[1]);

    // Check if the angles are equal and return the result
    return a1 == a2;
}

public static int findNthUglyNumber(int n) {
    int i2 = 0, i3 = 0, i5 = 0;
    int n2 = 2, n3 = 3, n5 = 5;
    int[] ugly = new int[n];
    ugly[0] = 1;
    for (int i = 1; i < n; i++) {
        int min = Math.min(n2, Math.min(n3, n5));
        ugly[i] = min;
        if (min == n2) {
            i2++;
            n2 = ugly[i2] * 2;
        }
        if (min == n3) {
            i3++;
            n3 = ugly[i3] * 3;
        }
        if (min == n5) {
            i5++;
            n5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

