public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    int i2 = 0, i3 = 0, i5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;

    uglyNumbers[0] = 1;

    for (int i = 1; i < n; i++) {
        int nextUglyNumber = Math.min(Math.min(nextMultipleOf2, nextMultipleOf3), nextMultipleOf5);
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            nextMultipleOf2 = uglyNumbers[++i2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            nextMultipleOf3 = uglyNumbers[++i3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            nextMultipleOf5 = uglyNumbers[++i5] * 5;
        }
    }

    return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int n2 = 2 * uglyNumbers[i2];
        int n3 = 3 * uglyNumbers[i3];
        int n5 = 5 * uglyNumbers[i5];
        uglyNumbers[i] = Math.min(Math.min(n2, n3), n5);
        if (uglyNumbers[i] == n2) i2++;
        if (uglyNumbers[i] == n3) i3++;
        if (uglyNumbers[i] == n5) i5++;
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    int longestSubstringLength = 0;
    int currentSubstringLength = 0;
    char currentChar = s.charAt(0);

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentSubstringLength++;
        } else {
            currentSubstringLength = 1;
            currentChar = s.charAt(i);
        }
        longestSubstringLength = Math.max(longestSubstringLength, currentSubstringLength);
    }

    return longestSubstringLength;
}

