    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == lastChar) {
            currentLength++;
        } else {
            if (currentLength > maxLength) {
                maxLength = currentLength;
            }
            currentLength = 1;
            lastChar = s.charAt(i);
        }
    }
    return Math.max(currentLength, maxLength);
}

