public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        result.add(i);
    }
    for (int i = 10; i <= n; i++) {
        int prev = i / 10;
        int suffix = i % 10;
        if (suffix < prev) {
            result.add(i);
        } else {
            result.add(10 * prev + suffix);
        }
    }
    return result;
}

