    for (int i = 1; i * i <= n; i++) {
        minNumSquares++;
        n -= i * i;
    }
    return minNumSquares;
}

public static int minPerfectSquareSum(int n) {
    int result = 0;
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        int j = n - (i * i);
        if (j > 0) {
            result += minPerfectSquareSum(j);
            count++;
        } else {
            result++;
        }
    }
    return result;
}

